import (
	"fmt"
)

var s []byte
var n, length int64

func check(a int64) int64 {
	var i int64
	for i = 1; i <= a-n; i++ {
		if s[length-i] != s[length-i-a] {
			return 0
		}
	}
	return 1
}

func main() {
	var input string
	fmt.Scan(&input)
	s = []byte(input)
	length = int64(len(s))
	fmt.Scan(&n)

	var i, k, j, ans int64 = 0, 0, 0, 0
	var key, max, min, temp int64 = 0, 0, 0, 0

	if n > length {
		min = (length + n) / 2
	} else {
		min = n
	}

	max = (length + n) / 2
	for i = 0; i < length; i++ {
		for j = 1; j*2+i <= length; j++ {
			key = 1
			for k = 1; k <= j; k++ {
				if s[i+k-1] != s[i+k+j-1] {
					key = 0
				}
			}
			if key == 1 {
				if j > temp {
					temp = j
				}
			}
		}
	}

	for i = max; i >= min && ans == 0; i-- {
		if check(i) == 1 {
			ans = i
		}
	}
	if min > ans {
		ans = min
	}
	if temp > ans {
		ans = temp
	}
	fmt.Printf("%d", 2*ans)
}

